(window.webpackJsonp=window.webpackJsonp||[]).push([[20],{457:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("说明：今年年初在一次飞行旅途中画了这幅画并分享给团契的弟兄姐妹。最近有个弟兄让我用文字再解释一下。")])],1),t._v(" "),v("p",[v("img",{attrs:{src:"/image/大学之道.jpg",alt:"大学之道"}})]),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("《大学》的开篇：“大学之道，在明明德”。意思是最根本的修行，在于显明人的“明德”——也即本有的光明的德性。中国的儒学发展到最高峰，应该就要算是王阳明的心学了。心学把这个“明德”又称为“心”，认为人的本心是光明的。要成为儒家的圣人，就是要通过各种修行，把自己的 “本心”彰显出来。而人的本心为何本来不彰呢？大概是人受到尘世风俗的污染，在思想里吸收了很多乌七八糟的东西，把本心遮盖住了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这个原理在中国北禅神秀大师写的一个偈子中也有体现：“身是菩提树，心为明镜台，常常勤拂拭，勿使惹尘埃”。人的心就像一个明镜，上面被各种俗尘杂念所遮盖。因此需要“常常勤拂拭”，让这光明的本心彰显出来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但这些不过都是人在自我陶醉中而臆想出来的道理，并不是真相。人的真相要由一个超越我们的神向我们揭开：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("圣经说，我们每个人实际上都是“死的”（以弗所书2：1）。也就是说，我们是与真正的生命源头——创造主——断绝的。这意味着我们的一切其实都与那圣洁的创造主不相匹配，是处在全然败坏的状态，从我们的肉体，到我们的意志、情感、理性，并深入到的本性——或者可以称作我们的“心”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("事实上，我们败坏的意志、情感和理性，正是这败坏的本性所产生的。正如耶稣所说：“从心里发出的，有恶念、苟合、偷盗、凶杀、奸淫、贪婪、邪恶、诡诈、淫荡、嫉妒、谤讟、骄傲、狂妄。”（马可福音7:21~23）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("按照儒家、佛家、道家、伊斯兰等等各种方法去修行，似乎能在一定程度上减轻自己的“邪情私欲”，但因为本性没有被改变，所以这都是治标不治本。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("圣经说“狗所吐的，它转过来又吃；猪洗净了又回到泥里去滚。”（彼得后书2:22）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("最深层次的本性不变，仅仅把外面的心思意念洗净、打扫干净，是没有用的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("要使狗、猪变得喜欢干净而不是那些脏东西，需要神迹。就是把猪性、狗性变成人性。人在本性上就不会去吃那吐出来的东西，也不会想要到泥里去打滚。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("同样，只有把人败坏的本性变为圣洁的本性，这个人才真的有了“明德”。在圣经中，这个过程叫做“重生”，是由圣灵来完成的(约翰福音3:5~6)。就人而言，表现出来就是他认罪悔改、信福音（以弗所书2:8）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("本性被改变之后，以前那个败坏的本性所生发出的败坏的理性、情感、意志仍然存在（有人称其为“罪的残留”）。这是因为人的肉身也是败坏的。这些败坏的理性、情感和意志就寓居在这个败坏的肉身当中，与新本性所生发的圣洁的理性、情感和意志相对抗。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当新本性仍不够彰显时，被重生的人就会被这些“罪的残留”所击败，从而犯罪。但这个本性一定会越来越彰显的。这是因为圣灵不仅重生人的本性，也内住在他所重生的人里面（约翰福音14:17）。圣灵会不断去浇灌这个新的本性，让其产生出越来越多的圣洁的理性、情感和意志。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以当被圣灵重生，有了“明德”（圣洁的本性）之后，要做的就是去彰显这个新本性。这就是“大学之道，在明明德”、“常常勤拂拭，勿使惹尘埃”的过程。在圣经中叫做“成圣”，或者叫“与罪争战”（彼得前书2:11），或者叫“心意更新而变化”（罗马书12:2）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这个过程要持续一生之久，除非被重生的人脱去了这个败坏的肉身（也就是肉身死亡），使“罪的残留”没有寓居之所（罗马书7:24；哥林多后书5:2）。当耶稣再来的时候，被重生的人会死而复活，获得一个荣耀的身体来安置那圣洁的灵魂（哥林多前书15:35~49），从而作为一个圣洁的人，永远与圣洁的神同在（马可福音12:26~27）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们已经说了，获得“明德”、被重生是圣灵的工作；而认罪悔改、信福音只是被重生之人的外在表现。那么在此之前，人能做什么呢？要信福音，首先得知道什么是福音。因此去认识福音，这是第一步（罗马书10:14）。带着谦卑、认真的心去寻求，神就必让他寻见（路11:9~13）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在“明明德”，或者“成圣”方面，也需要靠圣灵对本性的浇灌，人能做什么呢？圣灵是神，那当然就是不断与神亲近，以使自己越来越爱神、信任神。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("怎么才能与神亲近呢？就像一个人如何与另一个人亲近一样：不断交流、一起做事。")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);